/bin/bash -lc "python - <<'PY'
import urllib.request
for url in ['https://developers.openai.com/api/reference/resources/responses/methods/create', 'https://platform.openai.com/docs/guides/your-data']:
    try:
        body = urllib.request.urlopen(url, timeout=25).read().decode()
        from html.parser import HTMLParser
        class Text(HTMLParser):
            def handle_data(self, data):
                if data.strip(): self.parts.append(data.strip())
        p=Text(); p.parts=[]; p.feed(body)
        text=' '.join(p.parts)
        print(url)
        for term in ['store', 'input_text', 'output_text', '30 days', 'abuse monitoring']:
            i=text.lower().find(term.lower())
            if i>=0: print(text[max(0,i-150):i+650])
    except Exception as e: print(type(e).__name__, str(e))
PY"

